import pyomo.environ as pyo

DATA = {
    "capacity":  {"van": 6, "minibus": 10},
    "pollution": {"van": 7, "minibus": 10},
    "vehicles":  ["van", "minibus"],
    "min_kids": 150,
    "max_minibuses": 10,
    "van_exceeds_margin": 1,
}

GOLD_ANSWER = None


def build_model(data=None):
    d = data or DATA
    model = pyo.ConcreteModel()

    model.V = pyo.Set(initialize=d["vehicles"])

    def veh_bounds(m, v):
        if v == "minibus":
            return (0, d["max_minibuses"])
        return (0, None)

    model.x = pyo.Var(model.V, within=pyo.NonNegativeIntegers, bounds=veh_bounds)

    def obj_rule(m):
        return sum(d["pollution"][v] * m.x[v] for v in m.V)

    model.obj = pyo.Objective(rule=obj_rule, sense=pyo.minimize)

    def kids_rule(m):
        return sum(d["capacity"][v] * m.x[v] for v in m.V) >= d["min_kids"]

    model.kids = pyo.Constraint(rule=kids_rule)

    def max_minibus_rule(m):
        return m.x["minibus"] <= d["max_minibuses"]

    model.max_minibus = pyo.Constraint(rule=max_minibus_rule)

    def van_exceed_rule(m):
        return m.x["van"] >= m.x["minibus"] + d["van_exceeds_margin"]

    model.van_exceed = pyo.Constraint(rule=van_exceed_rule)

    return model
